// Snap + alignment-guide math (M2-WP4, FR-C2). Pure functions; DOM-free.
// Canvas grid defaults to 8 px (4 px token grid × 2); grid rendering and the
// toggle live in the canvas UI layer.

import type { Rect } from './viewport';

export const GRID_SIZE = 8;
export const GUIDE_THRESHOLD_PX = 4;

export interface RectDelta {
  dx: number;
  dy: number;
}

/** Snap a scalar to the nearest grid multiple. */
export function snapToGrid(v: number, grid = GRID_SIZE): number {
  return Math.round(v / grid) * grid;
}

/** Snap a rect's position (x, y); size preserved. */
export function snapRect(r: Rect, grid = GRID_SIZE): RectDelta {
  return { dx: snapToGrid(r.x, grid) - r.x, dy: snapToGrid(r.y, grid) - r.y };
}

/** Snap a resize by adjusting the rect so x/y/w/h all land on grid. */
export function snapResize(r: Rect, grid = GRID_SIZE): Rect {
  const x = snapToGrid(r.x, grid);
  const y = snapToGrid(r.y, grid);
  const x2 = snapToGrid(r.x + r.w, grid);
  const y2 = snapToGrid(r.y + r.h, grid);
  return {
    x,
    y,
    w: Math.max(grid, x2 - x),
    h: Math.max(grid, y2 - y),
  };
}

export interface Guide {
  axis: 'v' | 'h';
  /** Guide line position in canvas coords (x for v, y for h). */
  at: number;
  /** Object edge the guide came from (for tests/debug). */
  source: 'start' | 'center' | 'end';
}

export interface GuideResult {
  dx: number;
  dy: number;
  guides: Guide[];
}

function candidates(r: Rect): Array<{ at: number; source: Guide['source'] }> {
  return [
    { at: r.x, source: 'start' },
    { at: r.y, source: 'start' },
    { at: r.x + r.w / 2, source: 'center' },
    { at: r.y + r.h / 2, source: 'center' },
    { at: r.x + r.w, source: 'end' },
    { at: r.y + r.h, source: 'end' },
  ];
}

/**
 * Alignment guides: compare the moving rect's edges/centers against every
 * static rect; snap to the closest candidate within threshold, separately
 * per axis. Multiple guides on one axis are allowed (edge + center can both
 * fire on a shared coordinate) — renderer dedupes by coordinate.
 */
export function computeGuides(
  moving: Rect,
  others: Rect[],
  threshold = GUIDE_THRESHOLD_PX,
): GuideResult {
  const result: GuideResult = { dx: 0, dy: 0, guides: [] };
  let best: { axis: 'v' | 'h'; delta: number; guide: Guide } | null = null;

  for (const other of others) {
    for (const c of candidates(other)) {
      // vertical guide: aligns x coordinates
      for (const m of [moving.x, moving.x + moving.w / 2, moving.x + moving.w]) {
        const delta = c.at - m;
        const isX = m !== moving.y && m !== moving.y + moving.h / 2 && m !== moving.y + moving.h;
        if (!isX) continue;
        if (Math.abs(delta) <= threshold && (!best || best.axis !== 'v' || Math.abs(delta) < Math.abs(best.delta))) {
          if (best && best.axis === 'v' && Math.abs(delta) >= Math.abs(best.delta)) continue;
          best = { axis: 'v', delta, guide: { axis: 'v', at: c.at, source: c.source } };
          result.dx = delta;
        }
      }
      // horizontal guide: aligns y coordinates
      for (const m of [moving.y, moving.y + moving.h / 2, moving.y + moving.h]) {
        const delta = c.at - m;
        if (Math.abs(delta) > threshold) continue;
        if (best && best.axis === 'h' && Math.abs(delta) >= Math.abs(best.delta)) continue;
        best = { axis: 'h', delta, guide: { axis: 'h', at: c.at, source: c.source } };
        result.dy = delta;
      }
    }
  }
  result.guides.push(best?.guide ?? []);
  return result as GuideResult;
}
