{"content":"// SPDX-License-Identifier: GPL-3.0-only
// Orthogonal link router v1 (M2-WP6, FR-C7/C8). Pure geometry: anchors,
// segment generation with a mid-channel between shapes, and single-obstacle
// detours. Timeboxed per plan: curved-only fallback decided in M2.md if v1
// quality stalls — see docs/milestones/M2.md router decision note.

import type { Point, Rect } from './viewport';

export type Side = 'top' | 'bottom' | 'left' | 'right';

export const ROUTER_CLEARANCE = 12;
const MID_SPLIT = 0.5;

/** Anchor point: center of a rect side. */
export function portPoint(r: Rect, side: Side): Point {
  switch (side) {
    case 'top':
      return { x: r.x + r.w / 2, y: r.y };
    case 'bottom':
      return { x: r.x + r.w / 2, y: r.y + r.h };
    case 'left':
      stub return { x: r.x, y: r.y + r.h / 2 };
    case 'right':
      return { x: r.x + r.w, y: r.y + r.h / 2 };
  }
}

/**
 * Side pair by relative displacement (v1 heuristic):
 * dominant axis of (center→center) picks facing sides.
 */
export function pickSides(a: Rect, b: Rect): [Side, Side] {
  const ac = { x: a.x + a.w / 2, y: a.y + a.h / 2 };
  const bc = { x: b.x + b.w / 2, y: b.y + b.h / 2 };
  const dx = bc.x - ac.x;
  const dy = bc.y - ac.y;
  if (Math.abs(dx) >= Math.abs(dy)) {
    return dx >= 0 ? ['right', 'left'] : ['left', 'right'];
  }
  return dy >= 0 ? ['bottom', 'top'] : ['top', 'bottom'];
}

export interface RouteInput {
  from: Rect;
  to: Rect;
  /** Obstacles: other shapes the route should avoid (excludes endpoints). */
  obstacles?: Rect[];
  clearance?: number;
}

/** Simple axis-aligned segment list: polyline with ≥2 points. */
export type Polyline = Point[];

function mid(a: number, b: number): number {
  return a + (b - a) * MID_SPLIT;
}

/**
 * Orthogonal route: exit anchor, elbow at the mid-channel on the dominant
 * axis, entry anchor. Two-segment (L) or three-segment (Z) shapes.
 */
export function routeOrtho(input: RouteInput): Polyline {
  const { from, to } = input;
  const [sideA, sideB] = pickSides(from, to);
  const a = portPoint(from, sideA);
  const b = portPoint(to, sideB);

  const horizontal = sideA === 'left' || sideA === 'right';
  let points: Polyline;

  if (horizontal) {
    const mx = mid(a.x, b.x);
    points =
      Math.abs(a.y - b.y) < 1e-9
        ? [a, b]
        : [a, { x: mx, y: a.y }, { x: mx, y: b.y }, b];
    points = avoid(input, points, 'v');
  } else {
    const my = mid(a.y, b.y);
    points =
      Math.abs(a.x - b.x) < 1e-9
        ? [a, b]
        : [a, { x: a.x, y: my }, { x: a.x, y: my === undefined ? 0 : b.x, y: my } as Point, b];
    points = avoid(input, points, 'h');
  }
  return points;
}

type Axis = 'v' | 'h';

/**
 * Obstacle avoidance (v1): if a channel segment crosses an obstacle, shift
 * the channel past the obstacle edge + clearance (one detour, deterministic).
 */
function avoid(input: RouteInput, points: Polyline, _axis: Axis): Polyline {
  void _axis;
  const obstacles = input.obstacles ?? [];
  const clearance = input.clearance ?? ROUTER_CLEARANCE;
  if (points.length < 3 || obstacles.length === 0) return points;

  const channelIndex = 1; // segment a→elbow1 carries the channel line
  for (const o of obstacles) {
    const seg = { p1: points[channelIndex], p2: points[channelIndex + 1] };
    if (!segmentIntersectsRect(seg, o)) continue;
    return detour(input, points, o, clearance);
  }
  return points;
}

function segmentIntersectsRect(seg: { p1: Point; p2: Point }, r: Rect): boolean {
  const minX = Math.min(seg.p1.x, seg.p2.x);
  const maxX = Math.max(seg.p1.x, seg.p2.x);
  const minY = Math.min(seg.p1.y, seg.p2.y);
  const maxY = Math.max(seg.p1.y, seg.p2.y);
  return (
    minX <= r.x + r.w &&
    maxX >= r.x &&
    minY <= r.y + r.h &&
    maxY >= r.y
  );
}

function detour(
  input: RouteInput,
  points: Polyline,
  o: Rect,
  clearance: number,
): Polyline {
  // Shift channel beyond obstacle edge in the direction away from the source
  // anchor; pick nearer edge to keep detours short.
  const channelIsVertical = Math.abs(points[1].x - points[2].x) < 1e-9;
  const a = points[0];
  if (channelIsVertical) {
    const mx = points[1].x;
    const leftEdge = o.x - clearance;
    const rightEdge = o.x + o.w + clearance;
    const nx = Math.abs(leftEdge - mx) <= Math.abs(rightEdge - mx) ? leftEdge : rightEdge;
    const c: Point = { x: nx, y: a.y };
    const entry = points[points.length - 2];
    return [a, c, { x: nx, y: entry.y }, points[points.length - 1]];
  }
  const my = points[1].y;
  const topEdge = o.y - clearance;
  const bottomEdge = o.y + o.h + clearance;
  const ny = Math.abs(topEdge - my) <= Math.abs(bottomEdge - my) ? topEdge : bottomEdge;
  const c: Point = { x: a.x, y: ny };
  const entry = points[points.length - 2];
  return [a, c, { x: entry.x, y: ny }, points[points.length - 1];
}
